#include "cgal_search_with_point.h"

// object of class cgal_search_with_points
cgal_search_with_point search_with_point;
cgal_search_with_point search_with_point_bd;

cgal_search_with_point::cgal_search_with_point(){
}

cgal_search_with_point::~cgal_search_with_point(){
}

// initialize
int cgal_search_with_point::initialize(){
	int iflag, jflag, kflag;

	iflag = this->clearTree();
	jflag = this->clearPoints();
	kflag = this->clearSearch();

	return (iflag && jflag && kflag);
}

// add point with id
int cgal_search_with_point::addPoint(const int id, const double x, const double y, const double z){
	this->points.push_back(Point_3(x,y,z));
	this->indices.push_back(id);
	return 1;
}

// make data points tree
int cgal_search_with_point::makeTree(){
	this->pointTree.insert(boost::make_zip_iterator(boost::make_tuple(
			this->points.begin(),this->indices.begin())),
				    boost::make_zip_iterator(boost::make_tuple(
				    		this->points.end(),this->indices.end())) );
	return 1;
}

// search closest points
int cgal_search_with_point::searchClosestPoints(const int K, const double x, const double y, const double z,
		std::vector<int> &ids){
	K_neighbor_search search(this->pointTree, Point_3(x,y,z), K);
	for(K_neighbor_search::iterator it = search.begin(); it != search.end(); it++){
		ids.push_back(boost::get<1>(it->first));
	}

	return 1;
}

// search closest points
int cgal_search_with_point::searchClosestPoints2(const int K, const double x, const double y, const double z, int ids[]){
	K_neighbor_search search(this->pointTree, Point_3(x,y,z), K);
	for(K_neighbor_search::iterator it = search.begin(); it != search.end(); it++){
		this->ids_c_f.push_back(boost::get<1>(it->first));
	}
	for(int i=0;i<K;i++){
		ids[i] = this->ids_c_f[i];
	}

	return 1;
}

// search closest point
int cgal_search_with_point::searchClosestPoint(const double x, const double y, const double z,int &id){
	K_neighbor_search search(this->pointTree, Point_3(x,y,z),1);
	for(K_neighbor_search::iterator it = search.begin(); it != search.end(); it++){
		id = boost::get<1>(it->first);
	}

	return 1;
}

// clear data points tree
int cgal_search_with_point::clearTree(){
	this->pointTree.clear();
	return 1;
}

// clear data points
int cgal_search_with_point::clearPoints(){
	this->points.clear();
	this->indices.clear();
	return 1;
}

// clear search indes
int cgal_search_with_point::clearSearch(){
	this->ids_c_f.clear();
	return 1;
}

// clear data points and tree
int cgal_search_with_point::clearAll(){
	int iflag, jflag, kflag;

	iflag = this->clearTree();
	jflag = this->clearPoints();
	kflag = this->clearSearch();

	return (iflag && jflag && kflag);
}

